{
  "definition_simple": "流传在世的书籍版本。",
  "definition_standard": "文献学与版本学专有名词，指古籍在流传过程中保存、留存至今的各种抄本或印本。",
  "pos": "名词",
  "semantic_class": "concrete",
  "sentences": [
    {
      "tier": "T1",
      "mandarin": "这是一部古代小说的稀有传本。"
    },
    {
      "tier": "T2",
      "mandarin": "这本书最早的传本已经找不到了。"
    },
    {
      "tier": "T2",
      "mandarin": "博物馆里收藏着该诗集唯一的传本。"
    },
    {
      "tier": "T3",
      "mandarin": "学者们通过对比不同的传本，找到了许多文字差异。"
    },
    {
      "tier": "T3",
      "mandarin": "这部古书的早期传本中保存了作者的原貌。"
    },
    {
      "tier": "T4",
      "mandarin": "这部宋代文集的传本极少，堪称凤毛麟角。"
    },
    {
      "tier": "T4",
      "mandarin": "经过仔细考证，他发现这个传本并非宋代原刻，而是明代翻刻本。"
    },
    {
      "tier": "T5",
      "mandarin": "该书在流传过程中衍生出多个系统，各系统传本在篇目上大相径庭。"
    },
    {
      "tier": "T5",
      "mandarin": "整理古籍时必须先搜集该著作存世的所有传本，以便校勘讹误。"
    },
    {
      "tier": "T6",
      "mandarin": "《文心雕龙》的元刻本乃目前所见最早之刻本传本，对后世文本流变考辨意义重大。"
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "l1_audio_confusables": [
    {
      "word": "全本",
      "explanation": "声母不同（/tɕʰ/ 与 /tʂʰ/），“全本”指内容完整无缺的本子或整部大戏，与专指流传版本的“传本”容易听混。"
    },
    {
      "word": "串本",
      "explanation": "首字声调不同（第四声 chuàn 与第二声 chuán），听觉上极易因音调差异而产生混淆。"
    },
    {
      "word": "残本",
      "explanation": "声母不同（平舌音 /tsʰ/ 与翘舌音 /tʂʰ/），且均用于文献版本语境，发音相近且容易在听觉中并置。"
    }
  ],
  "primary_collocate": "存世",
  "collocation_distractors": [
    {
      "word": "畅销",
      "explanation": "“畅销”主要搭配现代商业化出版物，不能修饰专用于历史古籍流传版本的“传本”。"
    },
    {
      "word": "版权",
      "explanation": "“版权”是近现代法律概念，与传统古籍版本学领域的“传本”不存在固定搭配关系。"
    },
    {
      "word": "印刷",
      "explanation": "“印刷”为现代工业化生产动词，文献学中与传本搭配通常使用“刊印”、“雕版”或“传刻”。"
    }
  ],
  "collocation_wrong_collocate": "发售",
  "cloze_distractors": [
    {
      "word": "本领",
      "explanation": "字面含有“本”，但词义为技能或能力，放入古籍句式中在语义上完全不通。"
    },
    {
      "word": "传说",
      "explanation": "字面含有“传”，但词义为民间口耳相传的故事，与文献实体概念完全不符。"
    },
    {
      "word": "手稿",
      "explanation": "“手稿”指作者亲手写下的原始底稿，而“传本”强调后世流传存续下来的各类版本，二者在文献分类上概念不同。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "这家出版社下个月准备出版《红楼梦》的新传本。",
      "reason": "语域与语义冲突。“传本”特指历史上流传存世的古籍版本，现代出版社新印发行的书籍应称为“新版”或“新印本”，不能称为“新传本”。"
    },
    {
      "sentence": "他在图书馆借了一本小说，看完了立刻传本给室友。",
      "reason": "词性与句法结构错误。“传本”是名词，不能充当及物动词或离合词表示“把书传递给某人”。"
    },
    {
      "sentence": "这款电子书阅读软件上架了数万种高清排版的传本供用户付费下载。",
      "reason": "语义范畴错误。“传本”仅限于文献学、古籍版本学领域指代流传下来的物理印本或抄本，不能泛指现代数字化电子书。"
    }
  ],
  "spot_incorrect": {
    "sentence": "为了考证这部古籍的源流，教授特意从北京传本了一部善本到上海进行对比。",
    "error_description": "“传本”是名词（指流传下来的版本），句中将其误用作及物动词，混淆了词性与用法。",
    "corrected": "为了考证这部古籍的源流，教授特意从北京借调了一部善本到上海进行对比。"
  },
